def update_reservation_baggages(reservation_id: str, total_baggages: int, nonfree_baggages: int, payment_id: str):
    """
    Update the baggage information of a reservation.

    Args:
        reservation_id: The reservation ID, such as 'ZFA04Y'
        total_baggages: The updated TOTAL number of checked bags on the reservation (existing bags PLUS any newly added bags), across all passengers.
        nonfree_baggages: The number of those bags that are NOT free (each costs $50). Free-bag allowance per passenger by the booking user's membership and cabin: regular = basic_economy 0 / economy 1 / business 2; silver = 1 / 2 / 3; gold = 2 / 3 / 4. nonfree_baggages = max(0, total_baggages - free_allowance_per_passenger * number_of_passengers).
        payment_id: The payment id stored in user profile, such as 'credit_card_7815826', 'gift_card_7815826'. It MUST be the EXACT, FULL id copied from the user's profile (never shortened or invented).

    Returns:
        The updated reservation.

    Raises:
        ValueError: If the reservation is not found.
        ValueError: If the user is not found.
        ValueError: If the payment method is not found.
        ValueError: If the certificate cannot be used to update reservation.
        ValueError: If the gift card balance is not enough.
    """
    def _user_methods():
        try:
            res = env_get_reservation_details(reservation_id=reservation_id)
        except Exception:
            return {}
        if not isinstance(res, dict):
            return {}
        uid = res.get("user_id")
        if not uid:
            return {}
        try:
            u = env_get_user_details(user_id=uid)
        except Exception:
            return {}
        if isinstance(u, dict) and isinstance(u.get("payment_methods"), dict):
            return u["payment_methods"]
        return {}

    def _fmt_methods(methods):
        parts = []
        for pid, info in methods.items():
            if isinstance(info, dict):
                src = info.get("source")
                amt = info.get("amount")
                if amt is not None:
                    parts.append(f"{pid} (source={src}, balance={amt})")
                else:
                    parts.append(f"{pid} (source={src})")
            else:
                parts.append(str(pid))
        return parts

    def _fix_id(pid, valid):
        if not isinstance(pid, str) or not valid or pid in valid:
            return pid
        matches = [v for v in valid if v.startswith(pid) or pid.startswith(v)]
        return matches[0] if len(matches) == 1 else pid

    result = env_update_reservation_baggages(reservation_id=reservation_id, total_baggages=total_baggages, nonfree_baggages=nonfree_baggages, payment_id=payment_id)

    # ---- Recovery on a FAILED update only (success returns a reservation dict). ----
    if isinstance(result, str) and "Payment method not found" in result:
        valid = _user_methods()
        fixed = _fix_id(payment_id, valid)
        if fixed != payment_id:
            retry = env_update_reservation_baggages(reservation_id=reservation_id, total_baggages=total_baggages, nonfree_baggages=nonfree_baggages, payment_id=fixed)
            if not isinstance(retry, str):
                return retry
            result = retry
        if isinstance(result, str) and "Payment method not found" in result and valid:
            return (result + ". The user's ACTUAL payment methods on file are: "
                    + "; ".join(_fmt_methods(valid))
                    + ". Re-call update_reservation_baggages with one of these EXACT payment_id values.")

    return result
